/** @jsxImportSource @emotion/react */

import { useContext, useState, useEffect  } from "react";
import PageContainer from "../components/PageContainer.component";
import { UserContext } from "../contexts/user.context";
import RegisterForm from "../components/RegisterForm.component";
import {ButtonWithImage} from '../components/Buttons.components'
import { addProfile, addFoodCategory } from "../graphql/graphqlUtils";
import * as styles  from '../components/styles/Profile.css'
import { useNavigate, useLocation } from "react-router-dom";
import axios from "axios";
import { Dialog, DialogContent } from '@mui/material';
import ChangeAvatarDialog from "../components/ChangeAvatarDialog.component";

const Register = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, setProfiles, setCurrentProfile } = useContext(UserContext);
  const [isFormCompleated, setIsFormCompleated] = useState(false);
  const [customFoodCategories, setCustomFoodCategories] = useState([]);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [dialogType, setDialogType] = useState("addActivity");
  const [avatar, setAvatar] = useState(null);

    // Opens dialog 
    const openDialog = (dialogTypeNew) => {
      setDialogType(dialogTypeNew)
      setDialogOpen(true);
    };
  
    // Closes dialog
    const closeDialog = () => {
      setDialogOpen(false);
    };
  
    // Returns dialog component based on dialog type
    const getDialogContent = () => {
      if (dialogType === "avatar") { 
        return <ChangeAvatarDialog avatar={avatar ? URL.createObjectURL(avatar) : null} onSave={saveAvatar} onDelete={deleteAvatar} onClose={closeDialog}/>
      } else if (dialogType === "error") {
        
      } 
    };
  
    // Handles dialog submission
    const saveAvatar = async () => {
      try {
        // Create an input element to trigger file selection
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.onchange = async (event) => {
          const file = event.target.files[0];
          setAvatar(file)
          closeDialog();
        };
  
        // Trigger the file input click programmatically
        input.click();
      } catch (error) {
        console.error('Error selecting file:', error);
      }
    };

    // Handles dialog submission
    const uploadAvatar = async () => {
      if (avatar) {
        const data = new FormData();
        data.append('image', avatar);
        data.append('name', profile._id);
        data.append('destination', 'avatar');
        const result = await axios.post('/api/avatar', data);
      }
    };
  
    // Handles dialog submission
    const deleteAvatar = async () => {
      profile.avatar = ""
      setAvatar(null)
      closeDialog();
    };
  
    //Callback func that opens avatar dialog 
    const updateAvatar = async () => {
      openDialog("avatar")
    };
  
    // Function to fetch avatar data when component mounts
    const fetchAvatarUrl = async () => {
      try {
        const destination = 'avatar'
        const avatarResult = await axios.get(`/api/avatar/${profile?._id}?destination=${destination}`);
        profile.avatar = avatarResult.data
        return 
      } catch (error) {
        console.error("Error fetching avatar:", error);
      }
    };

  const redirectNow = () => {
    const redirectTo = location.search.replace("?redirectTo=", "");
    navigate(redirectTo ? redirectTo : "/");
  }

  let newProfile = {
    _id : "",
    name: "",
    activityType: "active",
    avatar: "",
    breed: "",
    categories: [customFoodCategories],
    dailyPortion: 250,
    dailyRatio: 5,
    weight: 5,
    deductCalories: false,
    dob: (new Date()).toISOString(),
    isCurrent: true,
    preset: "barfAdult",
    size: "small",
    userId: user.id,
    isRatioSelected: false,
  }

  // Some prefilled form state
  const [profile, setProfile] = useState(newProfile);

// Adds new Food Category
const addCategory= async (category) => {
  // Create a new array by copying the existing customFoodCategories and adding the new category
  const updatedCategories = [...customFoodCategories, category];
  // Update the state with the new array of custom food categories
  setCustomFoodCategories(updatedCategories);
};

// Deletes Food Category
const deleteCategory= async (categoryToDelete) => {
   // Filter out the category to be deleted
   const updatedCategories = customFoodCategories.filter(
    (category) => category.type !== categoryToDelete.type
  );

  // Update the state with the filtered array of custom food categories
  setCustomFoodCategories(updatedCategories);
};

const saveProfile = async () => {
  // Get avatar URL first and add generated url to new profile
  await fetchAvatarUrl()
  // Upload avatar to AWS S3
  await uploadAvatar()
  // Save new profile to DB
  const {profileNew, isCreated } = await addProfile(user, profile)  

  if (isCreated && profileNew) {
    console.log("SUCCESS to create Profile: ", profileNew)
    setProfiles([profileNew])
    setCurrentProfile(profileNew)


    // Add food categories from customFoodCategories array if preset is custom
    if (profileNew.preset === 'custom') {
      for (const category of customFoodCategories) {
        await addFoodCategory(user, profileNew, category)  
      }
    }

    redirectNow();
  } else { 
    alert("Profile cannot be created")
  }

};

// Deletes Food Category
const updateCategory= async (type, value) => {
  const newWeight = Math.floor(profile?.dailyPortion * value / 100)
  // Create a new array with the updated category
  const updatedCategories = customFoodCategories.map((category) =>
  category.type === type
    ? {
        ...category,
        percentage: value || 0,
        weight: newWeight,
      }
    : category
  );
  // Update the state with the new array
  setCustomFoodCategories(updatedCategories);
  
};

// Save the profile to local storage whenever it changes
useEffect(() => {
  console.log("useEffect ", profile)
}, [profile]);


  return <PageContainer>
    <RegisterForm 
      profile={profile} 
      avatar={avatar}
      customFoodCategories={customFoodCategories} 
      setProfile={setProfile} 
      addCategory={addCategory} 
      deleteCategory={deleteCategory} 
      updateCategory={updateCategory} 
      setIsFormCompleated ={setIsFormCompleated}
      updateAvatar={updateAvatar}
    />
    <div  style={styles.saveButtonContainerStyle}>
      <ButtonWithImage
         variant="addButton"
         width='100px'
         as='button'
         imageName="plus_round_fill_white_button.svg"
         imageSize={20}
         onClick={saveProfile}
         disabled = {!isFormCompleated}
        >
         SAVE
      </ButtonWithImage>
    </div>

    {/* Dialog */}
    {dialogOpen && (          
      <Dialog open={dialogOpen} >
        <DialogContent>
          {getDialogContent()}
          </DialogContent>
      </Dialog>
    )}
  </PageContainer>
}

export default Register;